reactiveclass Ping(10) {
  knownrebecs { Pong pong; }
  statevars { int count; }

  Ping() {
    count = 0;
  }

  msgsrv initial() {
    // no automatic start
  }

  msgsrv StartMessage() {
    pong.PingMessage();
  }

  msgsrv PongMessage() {
    count = count + 1;
    if (count >= 10) {
      pong.StopMessage();
      // no explicit stop in Rebeca; actor becomes quiescent
    } else {
      pong.PingMessage();
    }
  }
}

